import test from "node:test";
import assert from "node:assert/strict";
import { run, lastResult } from "../../src/invoice/index.ts";

const cases: Array<[number, number]> = [
  [0, 5346],
  [1, 6283],
  [7, 6089],
  [42, 10185],
];

test("invoice service matches the reference results", () => {
  for (const [x, expected] of cases) {
    assert.equal(run(x), expected, `run(${x})`);
    assert.equal(lastResult(x), expected);
  }
});

test("invoice service rejects invalid input", () => {
  assert.throws(() => run(-1), RangeError);
});
